func newLadingReplay() unsafe.Pointer { return unsafe.Pointer(new(ladingproject.LadingReplay)) }

func newNLadingReplay(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]ladingproject.LadingReplay, n)))
}

func ptrLadingReplay(p unsafe.Pointer, c int32) any {
	r := (*ladingproject.LadingReplay)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ProjectID))
	case 4:
		return (*string)(unsafe.Pointer(&r.VersionID))
	case 5:
		return (*string)(unsafe.Pointer(&r.AgainstVersionID))
	case 6:
		return &r.Map
	case 7:
		return &r.PeriodStart
	case 8:
		return &r.PeriodEnd
	case 9:
		return (*string)(unsafe.Pointer(&r.Status))
	case 10:
		return &r.Summary
	case 11:
		return &r.Items
	case 12:
		return &r.Error
	case 13:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 14:
		return &r.FinishedAt
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueLadingReplay(p unsafe.Pointer, c int32) any {
	r := (*ladingproject.LadingReplay)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ProjectID)
	case 4:
		return string(r.VersionID)
	case 5:
		return string(r.AgainstVersionID)
	case 6:
		return r.Map
	case 7:
		return r.PeriodStart
	case 8:
		return r.PeriodEnd
	case 9:
		return string(r.Status)
	case 10:
		if r.Summary == nil {
			return nil
		}
		return *r.Summary
	case 11:
		if r.Items == nil {
			return keel.EmptyJSONArray
		}
		return r.Items
	case 12:
		if r.Error == "" {
			return nil
		}
		return r.Error
	case 13:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 14:
		if r.FinishedAt == nil {
			return nil
		}
		return *r.FinishedAt
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

