func newLadingVersion() unsafe.Pointer { return unsafe.Pointer(new(ladingproject.LadingVersion)) }

func newNLadingVersion(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]ladingproject.LadingVersion, n)))
}

func ptrLadingVersion(p unsafe.Pointer, c int32) any {
	r := (*ladingproject.LadingVersion)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ProjectID))
	case 4:
		return &r.Number
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return (*string)(unsafe.Pointer(&r.ParentVersionID))
	case 7:
		return &r.Files
	case 8:
		return &r.Samples
	case 9:
		return &r.Manifest
	case 10:
		return &r.Readiness
	case 11:
		return &r.Notes
	case 12:
		return (*int64)(unsafe.Pointer(&r.ErrorCount))
	case 13:
		return (*int64)(unsafe.Pointer(&r.WarningCount))
	case 14:
		return &r.ShadowUntil
	case 15:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 16:
		return (*string)(unsafe.Pointer(&r.CertifiedByID))
	case 17:
		return &r.CertifiedAt
	case 18:
		return (*string)(unsafe.Pointer(&r.ActivatedByID))
	case 19:
		return &r.ActivatedAt
	case 20:
		return &r.SupersededAt
	case 21:
		return &r.ArchivedAt
	case 22:
		return &r.Version
	case 23:
		return &r.CreatedAt
	case 24:
		return &r.UpdatedAt
	}
	return nil
}

func valueLadingVersion(p unsafe.Pointer, c int32) any {
	r := (*ladingproject.LadingVersion)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ProjectID)
	case 4:
		return r.Number
	case 5:
		return string(r.Status)
	case 6:
		if r.ParentVersionID == "" {
			return nil
		}
		return string(r.ParentVersionID)
	case 7:
		if r.Files == nil {
			return keel.EmptyJSONArray
		}
		return r.Files
	case 8:
		if r.Samples == nil {
			return keel.EmptyJSONArray
		}
		return r.Samples
	case 9:
		return r.Manifest
	case 10:
		if r.Readiness == nil {
			return nil
		}
		return *r.Readiness
	case 11:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 12:
		return int64(r.ErrorCount)
	case 13:
		return int64(r.WarningCount)
	case 14:
		if r.ShadowUntil == nil {
			return nil
		}
		return *r.ShadowUntil
	case 15:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 16:
		if r.CertifiedByID == "" {
			return nil
		}
		return string(r.CertifiedByID)
	case 17:
		if r.CertifiedAt == nil {
			return nil
		}
		return *r.CertifiedAt
	case 18:
		if r.ActivatedByID == "" {
			return nil
		}
		return string(r.ActivatedByID)
	case 19:
		if r.ActivatedAt == nil {
			return nil
		}
		return *r.ActivatedAt
	case 20:
		if r.SupersededAt == nil {
			return nil
		}
		return *r.SupersededAt
	case 21:
		if r.ArchivedAt == nil {
			return nil
		}
		return *r.ArchivedAt
	case 22:
		return r.Version
	case 23:
		return r.CreatedAt
	case 24:
		return r.UpdatedAt
	}
	return nil
}

